"use client";

import React from "react";

interface CurrentObjectivePanelProps {
  currentObjective: string;
}

const CurrentObjectivePanel: React.FC<CurrentObjectivePanelProps> = ({
  currentObjective,
}) => {
  if (!currentObjective || currentObjective.trim() === "") {
    return null;
  }

  return (
    <div className="bg-gradient-to-r from-blue-900/50 to-purple-900/50 rounded-lg p-4 border border-blue-500/30 backdrop-blur-sm">
      <h3 className="text-lg font-semibold text-blue-300 mb-2 flex items-center">
        <svg
          className="w-5 h-5 mr-2"
          fill="none"
          stroke="currentColor"
          viewBox="0 0 24 24"
        >
          <path
            strokeLinecap="round"
            strokeLinejoin="round"
            strokeWidth={2}
            d="M9.663 17h4.673M12 3v1m6.364 1.636l-.707.707M21 12h-1M4 12H3m3.343-5.657l-.707-.707m2.828 9.9a5 5 0 117.072 0l-.548.547A3.374 3.374 0 0014 18.469V19a2 2 0 11-4 0v-.531c0-.895-.356-1.754-.988-2.386l-.548-.547z"
          />
        </svg>
        Mục Tiêu Hiện Tại
      </h3>
      <p className="text-gray-200 leading-relaxed">{currentObjective}</p>
    </div>
  );
};

export default CurrentObjectivePanel;
